def plan_for(document_hash,cik):
    row=REGISTRY.get(document_hash)
    if row is None or row['cik']!=str(int(cik)).zfill(10):return None
    base=template_plan(row['template'],cik)
    if base is None or base['plan_hash']!=row['template_plan_hash']:
        raise ValueError('Earlier statement semantic template changed')
    plan=deepcopy(base);plan.pop('plan_hash');plan['document_hash']=document_hash;plan['facts']=[]
    for item in row['items']:
        fact=deepcopy(base['facts'][item['index']]);fact['locator']['table']=item['table']
        if 'unit_locator' in fact:fact['unit_locator']['table']=item['table']
        for field in ('locator','table_proof','unit_locator'):
            if field in item:fact[field]=deepcopy(item[field])
        plan['facts'].append(fact)
    if digest(plan)!=row['plan_hash']:raise ValueError('Earlier statement mapping seal changed')
    return dict(plan,plan_hash=row['plan_hash'])
